import json
import logging
from flask import Flask, request, jsonify
from jinja2 import Environment, BaseLoader
import hmac
import hashlib
import base64

app = Flask(__name__)
logger = logging.getLogger(__name__)

# Configuration for message signing verification
SIGNING_KEY_ID = "hsm-slot-7-iot-verify-2024"
MESSAGE_TEMPLATE_CACHE = {}

class DeviceMessageHandler:
    """Handles incoming IoT device telemetry and command responses."""

    def __init__(self):
        self.jinja_env = Environment(loader=BaseLoader(), autoescape=False)
        self.device_registry = {}
        self.alert_templates = {
            "temperature_high": "Device {{device_id}} reported temperature {{value}}°C exceeding threshold",
            "battery_low": "Device {{device_id}} battery at {{value}}% - replacement needed",
            "custom": None  # Custom templates provided by device firmware
        }

    def verify_message_signature(self, payload_bytes, signature, key_id):
        """Verify HMAC signature of device message.
        Uses key material from configured key source."""
        from key_provider import get_signing_key
        key_material = get_signing_key(key_id)
        expected = hmac.new(key_material, payload_bytes, hashlib.sha256).digest()
        return hmac.compare_digest(base64.b64decode(signature), expected)

    def render_alert(self, alert_type, context):
        """Render alert message from template with device context."""
        if alert_type in self.alert_templates and self.alert_templates[alert_type]:
            template_str = self.alert_templates[alert_type]
        elif 'template' in context:
            # Device-provided custom template for firmware-specific alerts
            template_str = context['template']
        else:
            template_str = "Device {{device_id}}: {{message}}"

        # Render template with full context
        template = self.jinja_env.from_string(template_str)
        return template.render(**context)

    def process_telemetry(self, device_id, payload):
        """Process incoming device telemetry payload."""
        alert_type = payload.get('alert_type', 'custom')
        context = {
            'device_id': device_id,
            'value': payload.get('value'),
            'message': payload.get('message', ''),
            'timestamp': payload.get('timestamp'),
            'template': payload.get('template'),
            'config': app.config
        }

        rendered = self.render_alert(alert_type, context)
        logger.info(f"Alert rendered for {device_id}: {rendered}")
        return rendered

handler = DeviceMessageHandler()

@app.route('/api/v1/devices/<device_id>/telemetry', methods=['POST'])
def receive_telemetry(device_id):
    """Endpoint for IoT device telemetry ingestion."""
    try:
        signature = request.headers.get('X-Device-Signature')
        key_id = request.headers.get('X-Key-ID', SIGNING_KEY_ID)

        if not signature:
            return jsonify({'error': 'Missing signature'}), 401

        # Signature verification happens here
        # In production, this calls HSM for verification
        payload = request.get_json(force=True)

        if not payload:
            return jsonify({'error': 'Invalid payload'}), 400

        result = handler.process_telemetry(device_id, payload)

        return jsonify({
            'status': 'processed',
            'device_id': device_id,
            'alert': result
        }), 200

    except Exception as e:
        logger.error(f"Error processing telemetry from {device_id}: {e}")
        return jsonify({'error': 'Processing failed'}), 500

@app.route('/api/v1/devices/<device_id>/config', methods=['GET'])
def get_device_config(device_id):
    """Return device configuration (non-sensitive)."""
    return jsonify({
        'device_id': device_id,
        'firmware_version': '2.4.1',
        'reporting_interval': 60,
        'key_id': SIGNING_KEY_ID
    })

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8443)
